import json
import urllib.parse
import urllib.request as request
import ssl
import time

class URLReadError(Exception):
    pass

def is_valid_url(url):
    try:
        parsed = urllib.parse.urlparse(url)
        return parsed.scheme in ['http', 'https'] and bool(parsed.netloc)
    except Exception:
        return False

def readJSON(url, timeout=5):
    if not is_valid_url(url):
        raise URLReadError("Invalid URL")

    if not url.startswith('https://'):
        raise URLReadError("Insecure URL; must use HTTPS")

    context = ssl.create_default_context()
    start_time = time.time()

    try:
        with request.urlopen(url, context=context, timeout=timeout) as response:
            data = response.read()
            return json.loads(data)

    except urllib.error.URLError as e:
        raise URLReadError(f"Network error: {e.reason}")
    except json.JSONDecodeError:
        raise URLReadError("Invalid JSON response")
    except Exception as e:
        raise URLReadError(f"Unexpected error: {str(e)}")
    finally:
        elapsed_time = time.time() - start_time
        print(f"URL request completed in {elapsed_time:.2f} seconds")

