from flask import Flask, request, jsonify
from werkzeug.exceptions import HTTPException
from functools import wraps
import re

app = Flask(__name__)

# Define a rate limit decorator
def rate_limit(limit):
    requests_count = {}

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            ip = request.remote_addr
            if ip not in requests_count:
                requests_count[ip] = [0, None]  # count, timestamp
            count, timestamp = requests_count[ip]

            if timestamp is None or (time.time() - timestamp) > 60:  # reset count every minute
                requests_count[ip] = [1, time.time()]
            else:
                if count < limit:
                    requests_count[ip][0] += 1
                else:
                    return jsonify({"error": "rate limit exceeded"}), 429

            return func(*args, **kwargs)
        return wrapper
    return decorator

# Input validation for GitHub username
def is_valid_username(username):
    return re.match("^[a-zA-Z0-9-]{1,39}$", username) is not None

